def modular_sum(nums, m, sum):
    if m == 0:
        return True
    if sum == 0:
        return True
    if not nums:
        return False
    if len(nums) == 1:
        return nums[0] % m == 0

    dp = [False] * (sum + 1)
    dp[0] = True

    for num in nums:
        for i in range(sum, num - 1, -1):
            dp[i] = dp[i] or dp[i - num]

    return dp[sum]

