def radix_sort(arr):
    if not arr:
        return []
    if len(arr) == 1:
        return arr
    max_value = max(arr)
    exp = 1
    while max_value // exp > 0:
        count = [0] * 10
        for i in arr:
            index = (i // exp) % 10
            count[index] += 1
        for i in range(1, 10):
            count[i] += count[i - 1]
        output = [0] * len(arr)
        for i in range(len(arr) - 1, -1, -1):
            index = (arr[i] // exp) % 10
            output[count[index] - 1] = arr[i]
            count[index] -= 1
        arr = output
        exp *= 10
    return arr

